public static String getImage(AppConfig appConfig, SubmitApplicationRequest request, String type, String sparkVersion, String proxyUser) {
    if (request.getImage() == null || request.getImage().isEmpty()) {
        Optional<AppConfig.SparkImage> sparkImage = appConfig.resolveImage(type, sparkVersion);
        if (!sparkImage.isPresent()) {
            throw new WebApplicationException(String.format("Spark image not found for type: %s, version: %s", type, sparkVersion), Response.Status.BAD_REQUEST);
        }
        return sparkImage.get().getName();
    } else {
        logger.info("User {} is using a custom spark image {}", proxyUser, request.getImage());
        return request.getImage();
    }
}
